 C('ICOS pre event median',r['icos_pred0']['event_median'],e['icos']['pred0_event_median'],0.001); C('ICOS pre control median',r['icos_pred0']['control_median'],e['icos']['pred0_control_median'],0.001); C('ICOS pre P',r['icos_pred0']['p'],e['icos']['pred0_p'],0.0002)
