 C('CD95 rheum n',r['cd95']['rheum_n'],e['cd95']['rheum_n'],0); C('CD95 no-tox n',r['cd95']['no_toxicity_n'],e['cd95']['no_toxicity_n'],0); C('CD95 count rheum median',r['cd95']['count_rheum_median'],e['cd95']['count_rheum_median'],0.001); C('CD95 count no-tox median',r['cd95']['count_no_toxicity_median'],e['cd95']['count_no_toxicity_median'],0.001); C('CD95 freq CD4 rheum',r['cd95']['freq_cd4_rheum_median'],e['cd95']['freq_cd4_rheum_median'],0.001); C('CD95 freq CD4 no-tox',r['cd95']['freq_cd4_no_toxicity_median'],e['cd95']['freq_cd4_no_toxicity_median'],0.001)
 failed=[x for x in checks if not x[-1]]
 for name,a,b,t,ok in checks: print(('PASS' if ok else 'FAIL'),name,'actual=',a,'expected=',b,'tol=',t)
